const items = $input.all();

function createContext(value) {
    return {
        current: String(value ?? '').trim(),
        isNegative: false,
        numeric: null,
        result: null,
        invalid: false
    };
}

function caseEmpty(ctx) {
    if (!ctx.current) ctx.invalid = true;
}

function caseCurrencySymbol(ctx) {
    ctx.current = ctx.current
        .replace(/[$€£¥₪₹₩₺₽฿₫₴₦₲₵₡₢₣₤₥₧₨₭₮₯₰₱₳₶₷₸₹₻₼₾¢]/g, '')
        .replace(/\b[A-Z]{2,4}\b/g, '')
        .trim();
}

function caseNegative(ctx) {
    if (/^\(.*\)$/.test(ctx.current)) {
        ctx.isNegative = true;
        ctx.current = ctx.current.slice(1, -1).trim();
    } else if (ctx.current.startsWith('-')) {
        ctx.isNegative = true;
        ctx.current = ctx.current.replace(/^-+/, '');
    } else if (ctx.current.endsWith('-')) {
        ctx.isNegative = true;
        ctx.current = ctx.current.replace(/-+$/, '');
    } else if (ctx.current.includes('-')) {
        ctx.invalid = true;
    }
}

function caseInvalidChars(ctx) {
    // Allow apostrophe as thousands separator (e.g. 1'234.56)
    if (/[^\d.,()'\-\s]/.test(ctx.current)) ctx.invalid = true;
}

function caseStripNoise(ctx) {
    // Strip everything except digits, dot, comma
    ctx.current = ctx.current.replace(/[^\d.,]/g, '');
}

function caseNormalizeSeparators(ctx) {
    const dots   = (ctx.current.match(/\./g) || []).length;
    const commas = (ctx.current.match(/,/g)  || []).length;

    // Multiple of one separator: last one is always decimal
    if (dots > 1 || commas > 1) {
        const sep = dots > 1 ? '.' : ',';
        const lastIdx = ctx.current.lastIndexOf(sep);
        const after  = ctx.current.slice(lastIdx + 1);
        const before = ctx.current.slice(0, lastIdx).replace(new RegExp(`\\${sep}`, 'g'), '');
        // Always treat last separator as decimal regardless of digit count
        ctx.current = before + '.' + after;
        return;
    }

    // One dot and one comma: whichever comes last is the decimal separator
    if (dots === 1 && commas === 1) {
        const dotIdx   = ctx.current.indexOf('.');
        const commaIdx = ctx.current.indexOf(',');
        if (dotIdx > commaIdx) {
            // 1,234.56 → remove comma
            ctx.current = ctx.current.replace(',', '');
        } else {
            // 1.234,56 → remove dot, swap comma to dot
            ctx.current = ctx.current.replace('.', '').replace(',', '.');
        }
        return;
    }

    // Single separator — ambiguous
    const single = ctx.current.match(/^(\d+)[.,](\d+)$/);
    if (single) {
        const [, before, after] = single;
        const sep = ctx.current.includes('.') ? '.' : ',';
        // Treat as thousands only if: exactly 3 digits after, more than 2 digits before, and not all zeros
        const isThousands = after.length === 3 && before.length > 2 && !/^0+$/.test(after);
        if (isThousands) {
            ctx.current = ctx.current.replace(sep, '');
        } else {
            ctx.current = ctx.current.replace(sep, '.');
        }
    }
}

function caseAssumeImpliedDecimal(ctx) {
    // Only applies to pure digit strings long enough to have cents
    if (!/^\d+$/.test(ctx.current)) return;
    if (ctx.current.length <= 2) return;
    // Treat last 2 digits as decimal cents
    const intPart = ctx.current.slice(0, -2);
    const decPart = ctx.current.slice(-2);
    ctx.current = intPart + '.' + decPart;
}

function caseParseNumber(ctx) {
    const num = parseFloat(ctx.current);
    if (isNaN(num)) { ctx.invalid = true; return; }
    ctx.numeric = ctx.isNegative ? -Math.abs(num) : num;
}

function caseFormat(ctx) {
    if (ctx.invalid || ctx.numeric === null) return;
    const fixed = Math.abs(ctx.numeric).toFixed(2);
    const [intPart, decPart] = fixed.split('.');
    const withCommas = intPart.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
    ctx.result = (ctx.isNegative ? '-' : '') + withCommas + '.' + decPart;
}

const pipeline = [
    caseEmpty,
    caseNegative,
    caseCurrencySymbol,
    caseInvalidChars,
    caseStripNoise,
    caseNormalizeSeparators,
    caseAssumeImpliedDecimal,
    caseParseNumber,
    caseFormat
];

function normalizeCurrency(value) {
    const ctx = createContext(value);
    for (const fn of pipeline) {
        fn(ctx);
        if (ctx.invalid) return null;
    }
    return ctx.result;
}

for (const item of items) {
    item.json.result = normalizeCurrency(item.json.result);
}

return $input.all();
